    """Decorator that requires the user to have a specific permission code.

    Checks both the JWT claims (fast path) and the database (authoritative
    source).  The DB check ensures the permission grant is scoped to the
    caller's current organization context, closing the gap where a JWT
    minted for org-A could be replayed against objects in org-B.

    Args:
        permission_code: The permission code to check (e.g., "booking.create").
    """
    def decorator(f):
        @functools.wraps(f)
        def decorated(*args, **kwargs):
            current_user = getattr(g, "current_user", None)
            if current_user is None:
                return error_response("UNAUTHORIZED", "Authentication required", status_code=401)

            # Fast-path: check JWT claims first
            if permission_code not in (current_user.permissions or []):
                logger.warning(
                    "security", "auth",
                    f"Missing permission: user={current_user.user_id} needs={permission_code}"
                )
                return error_response("PERMISSION_DENIED", "Missing required permission", status_code=403)

            # Authoritative DB check: verify the grant exists for the user's
            # current org context (or as a global/unscoped grant).
            from src.models.models import Permission, UserPermission
            org_id = getattr(current_user, "organization_id", None)
            db_grant = db.session.query(UserPermission.id).join(
                Permission, Permission.id == UserPermission.permission_id
            ).filter(
                Permission.code == permission_code,
                UserPermission.user_id == current_user.user_id,
            )
            if org_id:
                db_grant = db_grant.filter(
                    db.or_(
                        UserPermission.organization_id == org_id,
                        UserPermission.organization_id.is_(None),
                    )
                )
            else:
                db_grant = db_grant.filter(UserPermission.organization_id.is_(None))

            if not db_grant.first():
                # Platform admins bypass permission grants
                if current_user.role != RoleType.PLATFORM_ADMIN.value:
                    logger.warning(
                        "security", "auth",
                        f"DB permission check failed: user={current_user.user_id} "
                        f"perm={permission_code} org={org_id}"
                    )
                    return error_response("PERMISSION_DENIED", "Missing required permission for this organization", status_code=403)

            return f(*args, **kwargs)
        return decorated
    return decorator"}

